from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from constance import config

class OrganizationWebhookDispatcherConfigView(APIView):
    permission_classes = [IsAuthenticated]

    def put(self, request, org_id):
        if request.user.organization_id != int(org_id) or not request.user.is_org_admin:
            return Response({"error": "Unauthorized to modify organization webhook settings"}, status=403)

        target_url = request.data.get("webhook_url")
        constance_key = f"ORG_{org_id}_OUTBOUND_EVENT_URL"

        if not hasattr(config, constance_key):
            return Response({"error": "Organization webhook slot not provisioned"}, status=404)

        setattr(config, constance_key, target_url)
        return Response({"status": "updated", "organization_id": org_id, "url": target_url})
